<?php $e=static fn(mixed $v):string=>App\Core\View::e($v);$csrf=App\Core\Security::csrfToken();$moment=['before_match'=>'Antes da partida','during_match'=>'Durante a partida','after_match'=>'Depois da partida','final_documentation'=>'Documentação final'];$byItem=[];foreach($items as $item)$byItem[(int)($item['checklist_item_id']??0)][]=$item; ?>
<section class="page-stack"><div class="section-heading"><div><p class="eyebrow"><?= $e($match['championship_name']) ?></p><h1>Evidências da partida</h1><p><?= $e($match['home_team_name']) ?> x <?= $e($match['away_team_name']) ?></p></div><div class="quick-actions"><a class="button secondary" href="<?= $e(App\Core\Config::url('/admin/partidas/'.$match['id'].'/operacao')) ?>">Central operacional</a><a class="button secondary" href="<?= $e(App\Core\Config::url('/admin/dias-evento?championship_id='.(int)$match['championship_id'])) ?>">Evidências do dia</a></div></div><?php if($message): ?><p class="success"><?= $e($message) ?></p><?php endif; ?>
