<?php foreach($checklist as $entry): $files=$byItem[(int)$entry['id']]??[]; ?><article class="panel"><p class="eyebrow"><?= $e($moment[$entry['expected_moment']]??$entry['expected_moment']) ?> · <?= (int)$entry['is_required']?'Obrigatório':'Opcional' ?></p><h2><?= $e($entry['name']) ?></h2><p><?= $e($entry['description']) ?></p><p class="muted"><?= (int)$entry['approved_files'] ?>/<?= (int)$entry['min_files'] ?> aprovadas · máximo <?= (int)$entry['max_files'] ?></p><?php if($canUpload&&count($files)<(int)$entry['max_files']): ?><form method="post" enctype="multipart/form-data" class="form-grid" action="<?= $e(App\Core\Config::url('/admin/partidas/'.$match['id'].'/evidencias')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="checklist_item_id" value="<?= $e($entry['id']) ?>"><label>Arquivos<input type="file" name="files[]" multiple required accept="<?= $e($entry['allowed_mime_types']) ?>" capture="environment"><span class="muted">No celular, escolha os arquivos ou abra a câmera.</span></label><label>Substituir arquivo<select name="replace_media_id"><option value="">Não substituir</option><?php foreach($files as $file):if($file['review_status']!=='approved'): ?><option value="<?= $e($file['id']) ?>"><?= $e($file['original_name']) ?></option><?php endif;endforeach; ?></select></label><label>Observação<?= (int)$entry['notes_required']?' *':'' ?><textarea name="caption" maxlength="500"></textarea></label><label>Data e hora<input type="datetime-local" name="captured_at"></label><button>Enviar para análise</button><button class="secondary" name="save_as_draft" value="1">Salvar rascunho</button></form><?php endif; ?><?php foreach($files as $file): ?><div class="panel"><a href="<?= $e(App\Core\Config::url('/admin/partidas/'.$match['id'].'/evidencias/'.$file['id'])) ?>" target="_blank">Visualizar ou baixar: <?= $e($file['original_name']) ?></a><p><?= $e($file['caption']?:'Sem observação.') ?> · <?= $e($file['uploader_name']) ?> · <?= $e($file['created_at']) ?></p><p class="muted">Situação: <?= $e(['submitted'=>'Em análise','approved'=>'Aprovada','rejected'=>'Rejeitada','draft'=>'Rascunho'][$file['review_status']]??$file['review_status']) ?></p><?php if($canUpload&&$file['review_status']==='draft'): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/partidas/'.$match['id'].'/evidencias/'.$file['id'].'/enviar')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button>Enviar rascunho para análise</button></form><?php endif; ?><?php if($canUpload): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/partidas/'.$match['id'].'/evidencias/'.$file['id'].'/observacao')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Corrigir observação<textarea name="caption" maxlength="500"><?= $e($file['caption']) ?></textarea></label><button class="secondary">Salvar observação</button></form><?php endif; ?><?php if($canRemove&&$file['review_status']!=='approved'): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/partidas/'.$match['id'].'/evidencias/'.$file['id'].'/remover')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Motivo<input name="reason" maxlength="1000"></label><button class="secondary">Remover antes da aprovação</button></form><?php endif; ?><?php if($canApprove&&$file['review_status']==='submitted'): ?><form method="post" class="form-grid" action="<?= $e(App\Core\Config::url('/admin/partidas/'.$match['id'].'/evidencias/'.$file['id'].'/revisar')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Decisão<select name="decision"><option value="approved">Aprovar</option><option value="rejected">Rejeitar</option></select></label><label>Motivo de rejeição<textarea name="reason" maxlength="1000"></textarea></label><button>Registrar análise</button></form><?php endif; ?></div><?php endforeach; ?></article><?php endforeach; ?>
<?php if($canUpload&&$checklist===[]): ?><article class="panel"><h2>Enviar evidencia livre</h2><form method="post" enctype="multipart/form-data" class="form-grid" action="<?= $e(App\Core\Config::url('/admin/partidas/'.$match['id'].'/evidencias')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Titulo<input name="title" required maxlength="180"></label><label>Arquivos<input type="file" name="files[]" multiple required accept="image/jpeg,image/png,image/webp" capture="environment"><span class="muted">No celular, escolha arquivos ou use a câmera.</span></label><label>Observacao<textarea name="caption" maxlength="500"></textarea></label><button>Enviar evidencia</button></form></article><?php endif; ?>
 <article class="panel"><h2>Historico documental</h2><ul><?php foreach($history as $row): ?><li><?= $e($row['created_at']) ?> · <?= $e($row['user_name']) ?> · <?= $e($row['action']) ?><?= $row['details']?' · '.$e($row['details']):'' ?></li><?php endforeach; ?><?php if($history===[]): ?><li>Nenhuma movimentacao registrada.</li><?php endif; ?></ul></article><script>document.querySelectorAll('input[type=file][name="files[]"]').forEach((input)=>input.setAttribute('capture','environment'));</script></section>
